WFJ.Data.add("spell", {
  [409073] = { "近接攻撃で怒りを$N1生み出します。", nil, 0x92c24d5d, nil, "um" },
  [409163] = { "ベルトにFocused Rageのルーンを刻みます：\n\n$I1\n攻撃アビリティの怒りコストを$N1減らします。", nil, 0xbd819656, nil, "um" },
  [409239] = { "$N1ヤード以内のすべての対象に即座に両方の武器を投げつけ、武器ダメージの$N2%を与えます。", nil, 0x989dea54, nil, "um" },
  [409240] = { "$N1ヤード以内のすべての対象に即座に両方の武器を投げつけ、短剣では武器ダメージの$N2%、その他すべての武器では武器ダメージの$N3%を与えます。", nil, 0x9f297d5b, nil, "um" },
  [409324] = { "次の$D1の間、与えたダメージの$N2%が近くのパーティメンバー最大$N3人への回復に変換され、回復量の$N4%が直近のFlame Shockの対象へのダメージに変換されます。", "ダメージを周囲のパーティーメンバーへの治療に変換し、治療をFlame Shockの目標へのダメージに変換します。", 0xa920f4c5, 0xabc76e9a, "uu" },
  [409333] = { "次の$D1の間、与えたダメージの$N2%が近くのパーティメンバー最大$N3人への回復に変換され、回復量の$N4%が直近のFlame Shockの対象へのダメージに変換されます。", nil, 0xef189613, nil, "um" },
  [409337] = { "次の$D1の間、与えたダメージの$N2%が近くのパーティメンバー最大$N3人への回復に変換され、回復量の$N4%が直近のFlame Shockの対象へのダメージに変換されます。", nil, 0xef189613, nil, "um" },
  [409365] = { nil, "攻撃速度。", nil, 0x62b8a592, "mu" },
  [409368] = { "ペットの与えるダメージと体力が$N1%増加し、Focusの回復速度が$N2%上昇します。さらに、ペットのGrowlが$D1の間、対象をTauntしてペットを攻撃させるようにもなります。", nil, 0x0e6fe86a, nil, "um" },
  [409372] = { "対象を挑発して自分を攻撃させます。ただし、対象がすでに自分を攻撃している場合は効果がありません。", "挑発されています。", 0x71de38fd, 0x36f56123, "uu" },
  [409379] = { "殺せと命令を下し、$D1の間、ペットのClawとBiteのダメージを$N1%増加させます。ペットがClawまたはBiteを使うたびに、ダメージボーナスは$N3%減少します。", nil, 0x912d6e1b, nil, "um" },
  [409396] = { "仕留めるよう命令し、$D1の間、ペットのClawとBiteで与えるダメージを$N1%増加させます。ペットがClawまたはBiteを使うたびに、ダメージボーナスが$N3%減少します。", "ClawとBiteで与えるダメージが$N1%増加します。", 0x912d6e1b, 0xce508390, "uu" },
  [409418] = { "仕留めるよう命令し、$D1の間、ペットのClawとBiteのダメージを$N1%増加させます。ペットがClawまたはBiteを使うたびに、ダメージボーナスが$N3%減少します。", "ClawとBiteで与えるダメージが$N1%増加します。", 0x22bcaf5c, 0x952b882c, "uu" },
  [409428] = { "クリティカル率が$N1%上昇し、すべてのShotのアビリティのマナコストが$N2%減少します。", nil, 0x2cf87e48, nil, "um" },
  [409433] = { "武器ダメージの$N1%を与え、対象にかかっている現在のStingを更新し、効果を発動させます：\n\nSerpent Sting - Serpent Stingで与えたダメージの$N2%を即座に与えます。\n\nViper Sting - Viper Stingで吸収した総量の$N3%に等しいマナを即座に回復します。\n\nScorpid Sting - $D1の間、対象をDisarmしようとします。この効果は$N5分に一度しか発生しません。", nil, 0x1ccad7e0, nil, "um" },
  [409493] = { "武器ダメージの$N1%を与え、対象にかかっている現在のStingを更新し、効果を発動させます：\n\nSerpent Sting - Serpent Stingで与えたダメージの$N2%を即座に与えます。\n\nViper Sting - Viper Stingで吸収した総量の$N3%に等しいマナを即座に回復します。\n\nScorpid Sting - $D1の間、対象をDisarmしようとします。この効果は$N5分に一度しか発生しません。", nil, 0x1ccad7e0, nil, "um" },
  [409494] = { "武器ダメージの$N1%を与え、対象にかかっている現在のStingを更新し、効果を発動させます：\n\nSerpent Sting - Serpent Stingで与えたダメージの$N2%を即座に与えます。\n\nViper Sting - Viper Stingで吸収した総量の$N3%に等しいマナを即座に回復します。\n\nScorpid Sting - $D1の間、対象をDisarmしようとします。この効果は$N5分に一度しか発生しません。", nil, 0x1ccad7e0, nil, "um" },
  [409495] = { "武器ダメージの$N1%を与え、対象にかかっている現在のStingを更新し、効果を発動させます：\n\nSerpent Sting - Serpent Stingで与えたダメージの$N2%を即座に与えます。\n\nViper Sting - Viper Stingで吸収した総量の$N3%に等しいマナを即座に回復します。\n\nScorpid Sting - $D1の間、対象をDisarmしようとします。この効果は$N5分に一度しか発生しません。", "武器を奪われています。", 0x1ccad7e0, 0x98985eda, "uu" },
  [409504] = { "近接攻撃と遠隔攻撃のクリティカルにより、$D1の間、現在の敏捷性の$N1%だけ攻撃力が上昇します。", nil, 0xe5905d7e, nil, "um" },
  [409507] = { "遠隔攻撃のクリティカルにより、$D1の間、敏捷性の$N1%だけ攻撃力が上昇します。", "Attack Powerが$N1増加します。", 0xe1757db0, 0x44b5cb33, "uu" },
  [409580] = { "ハンターが獅子の心を呼び起こし、周囲の味方全員のすべての能力値を$N1%、Attack Powerを$N2上昇させ、ハンター自身のすべての能力値をさらに$N3%上昇させます。", "ハンターの能力値が$N1%上昇します。", 0xda4d40c0, 0x077a68f0, "uu" },
  [409583] = { "ハンターが獅子の心を呼び起こし、近くのすべての味方の総合能力値を$N1%上昇させ、ハンター自身の総合能力値をさらに$N2%上昇させます。", "能力値が$N1%、Attack Powerが$N2増加します。", 0x35b31cc8, 0xb8d3cc6d, "uu" },
  [409593] = { "手負いの対象にとどめを刺そうと遠隔攻撃を放ち、武器ダメージの$N1%に加えて$N2のダメージを与えます。Kill Shotには最小射程がありません。体力が20%以下の敵に使用すると、Kill Shotのクールダウンがリセットされます。", nil, 0xeae59b96, nil, "um" },
  [409687] = { "オフハンド武器の与えるダメージが$N1%増加し、二刀流の間はRaptor Strikeが両方の武器で攻撃するようになります。", nil, 0x096cde57, nil, "um" },
  [409691] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
  [409693] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
  [409748] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
  [409750] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
  [409751] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
  [409752] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
  [409754] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
  [409755] = { "近接ダメージを$N1増加させる強力な攻撃です。", nil, 0xac0dc93d, nil, "um" },
  [409805] = { "Wild Strikesのアビリティを得ます：\n\n$I1\nCat Form、Bear Form、Dire Bear Formの間、$N1ヤード以内のパーティーまたはレイドのメンバーの戦闘の猛々しさが増します。近接攻撃が命中するたびに、$N2%の確率で、攻撃者はAttack Powerが$N3%追加された追加攻撃を行います。対象がすでにWindfury Totemの恩恵を受けている場合は効果がありません。", nil, 0x788aa8b1, nil, "um" },
  [409809] = { "Survival Instinctsのアビリティを得ます：\n\n$I1\n使用すると、$D1の間、最大体力の$N1%を得て、自分が行うPhysical以外のすべての治癒が$N2%増加します。効果が切れると、その体力は失われます。Moonkin Form以外のすべての形態で使用できます。\n\nさらに、Bear FormまたはDire Bear Formの間に回避するたびに怒りを$N4、Cat Formの間はエネルギーを$N5、その他の形態の間は最大マナの$N6%を回復します。", nil, 0x073a0328, nil, "um" },
  [409810] = { "Wild Growthのアビリティを得ます：\n\n$I1\n$D1かけて対象とそのパーティーの体力を$N1回復します。パーティーメンバーは対象から$N3ヤード以内にいる必要があります。回復量は最初は速く適用され、Wild Growthが効果時間の終わりに近づくにつれて遅くなります。", nil, 0x1229731d, nil, "um" },
  [409813] = { "Eclipseのアビリティを得ます：\n\n$I1\nWrathの呪文が、次の$N1回のStarfireの呪文の詠唱時間を$D1短縮します。最大$N3回分までチャージを蓄えます。$D2持続します。", nil, 0x2e5d5870, nil, "um" },
  [409819] = { { "Savage Roarのアビリティを得ます：\n\n$I1\n|CFFFFFFFF必要：Cat Form|R\nフィニッシュ技です。Cat Formの間、与えるPhysicalダメージを$N1%増加させます。コンボポイントが多いほど長く持続します：\n 1ポイント：$N3秒\n 2ポイント：$N5秒\n 3ポイント：$N7秒\n 4ポイント：$N9秒\n 5ポイント：$N11秒", "Savage Roarのアビリティを得ます：\n\n$I1\n|CFFFF2020必要：Cat Form|R\nフィニッシュ技です。Cat Formの間、与えるPhysicalダメージを$N1%増加させます。コンボポイントが多いほど長く持続します：\n 1ポイント：$N3秒\n 2ポイント：$N5秒\n 3ポイント：$N7秒\n 4ポイント：$N9秒\n 5ポイント：$N11秒", shape = { "11/0", "11/0" } }, nil, 0xb2ad9246, nil, "um" },
  [409824] = { "RejuvenationとLifebloomのアビリティのグローバルクールダウンを$D1短縮し、Lifebloomのアビリティを得ます：\n\n$I1\n$D2かけて対象の体力を$N2回復します。Lifebloomが効果時間を終えるか解除されると、対象は即座に体力を$N4回復し、ドルイドは呪文のコストの半分を取り戻します。この効果は同じ対象に最大$N5回までスタックします。", nil, 0x2e4374dc, nil, "um" },
  [409826] = { "Nature's Furyのアビリティを得ます：\n\n$I1\n$D1の間、治癒力がNature呪文ダメージの$N1%だけ増加します。", nil, 0x7b50d5d3, nil, "um" },
  [409830] = { "Nourishのアビリティを得ます：\n\n$I1\n味方の対象の体力を$N1回復します。対象にRejuvenation、Regrowth、Lifebloom、Wild Growthのいずれかの効果がかかっている場合、さらに20%多く回復します。この呪文はHealing TouchまたはRegrowthに関連するすべての効果の恩恵を受け、それらを発動させます。", nil, 0x2ef6e8eb, nil, "um" },
  [409831] = { "Dreamstateのアビリティを得ます：\n\n$I1\n非周期のダメージ呪文がクリティカルになると、$D1の間、詠唱中もマナ回復の$N1%が継続します。", nil, 0xc097fe72, nil, "um" },
  [409832] = { "Fury of Stormrageのアビリティを得ます：\n\n$I1\nWrathのマナコストを$N1%減少させ、Wrathでダメージを与えるたびに$N2%の確率で、$D1以内に次に詠唱するHealing Touchが即時詠唱になり、どの変身形態でも詠唱できるようになります。Tree of Life形態の間もWrathを詠唱できるようになります。", nil, 0x58a6d63b, nil, "um" },
  [409856] = { "倒れた冒険者の魂を解き放つ儀式を始めます。", nil, 0x1348cc33, nil, "um" },
  [409918] = { nil, "インスピレーションに満ちています。", nil, 0x12978998, "mu" },
  [409922] = { "Hammer of the Righteousのアビリティを得ます：\n\n$I1\n現在の対象と、近くにいる追加の対象最大$N1体をハンマーで打ち、それぞれにメインハンド武器の秒間ダメージの$N2倍に等しいHolyダメージを与えます。クールダウンはCrusader Strikeと共有です。", nil, 0x41bcfc78, nil, "um" },
  [409924] = { "Divine Stormのアビリティを得ます：\n\n$I1\n即時の武器攻撃で、$N3ヤード以内の敵最大$N2体に武器ダメージの$N1%を与えます。Divine Stormは、与えたダメージの合計$N5%分、パーティーまたはレイドのメンバー最大3人を回復します。", nil, 0x1d2c1934, nil, "um" },
  [409925] = { "Divine Lightのアビリティを得ます：\n\n$I1\n味方の対象の体力を$N1回復します。対象への過剰回復の$N2%は、$D1持続する吸収シールドに変換されます。Divine Lightを複数回詠唱しても、このシールドは蓄積しません。\n\nDivine Lightは、Holy Lightから発動する、またはHoly Lightを強化するすべての才能と効果の恩恵を受けます。", nil, 0xbbe5ffdd, nil, "um" },
  [409930] = { nil, "ひらめきに満ちています。", nil, 0x12978998, "mu" },
  [409934] = { "Avenging Wrathのアビリティを得ます：\n\n$I1\n$D1の間、与えるすべてのダメージと治癒が$N1%増加します。Forbearanceを引き起こし、Forebearanceが有効な間は使用できません。", nil, 0x21255755, nil, "um" },
  [409935] = { "Hand of Sacrificeのアビリティを得ます：\n\n$I1\n対象のパーティーまたはレイドのメンバーが受けるダメージの$N1%を術者に移します。$D1、または術者が最大体力の$N3%を移し終えるまで持続します。", nil, 0x043ae106, nil, "um" },
  [409936] = { "Inspiration Exemplarのアビリティを得ます：\n\n$I1\n鼓舞する存在感により、近くのパーティーメンバーのFearとSleepの効果を定期的に解除します。", nil, 0x338ec99b, nil, "um" },
  [409938] = { "Fire Novaのアビリティを得て、Fire Nova Totemと置き換えます：\n\n$I1\nFire Nova Totemの呪文がFire Novaに置き換わります。Fire Novaは現在のFireトーテムからその位置にダメージを放出させます。", nil, 0xac6b1f14, nil, "um" },
  [409940] = { "Dual Wield Specializationのアビリティを得ます：\n\n$I1\n二刀流の間、呪文と近接攻撃の両方の命中率が$N1%上昇し、Stormstrikeのアビリティが二刀流時に両方の武器で命中するようになり、オフハンド武器の与えるダメージが$N2%増加します。", nil, 0x93277d64, nil, "um" },
  [409941] = { "Water Shieldのアビリティを得ます：\n\n$I1\n術者は水の球$N1個に囲まれます。呪文、近接攻撃、遠隔攻撃が術者に命中したとき、または術者の治癒呪文がクリティカルになったとき、水の球を一つ消費して最大マナの$N2%を術者に回復します。球は数秒に一つしか発動しません。$D1持続します。\n\nシャーマンに同時に有効にできるElemental Shieldは一つだけです。", nil, 0x5c50298d, nil, "um" },
  [409943] = { "Shield Masteryのアビリティを得ます：\n\n$I1\nBlockするたびに、最大マナの$N1%に等しいマナを回復し、盾のアーマー値の$N2%に等しいアーマーを得ます。最大$N3回までスタックします。また、Blockの確率が常に$N4%上昇し、Block値が$N5%上昇します。\n\nさらに、Shockのアビリティを使用するたびに、防御スキルが$N7を超えるポイントごとにSpell Damageを$N6得ます。$D1持続します。", nil, 0xd7939443, nil, "um" },
  [409944] = { "Ancestral Guidanceのアビリティを得ます：\n\n$I1\n次の$D1の間、与えるダメージの$N2%が近くのパーティーメンバー最大3人への治癒に変換され、行う治癒の$N4%が直近のFlame Shockの対象へのダメージに変換されます。", nil, 0x0da0019e, nil, "um" },
  [409945] = { "Overloadのアビリティを得ます：\n\n$I1\nLightning BoltとChain Lightningの呪文に、$N1%の確率で同じ対象に追加コストなしで同様の呪文をもう一度放つ効果を与えます。その呪文のダメージは半分で、脅威は発生しません。", nil, 0x7b4659a8, nil, "um" },
  [409946] = { "Maelstrom Weaponのアビリティを得ます：\n\n$I1\n近接攻撃でダメージを与えると、一定の確率で次のLightning Boltの呪文の詠唱時間とマナコストを$N1%減少させます。最大$N2回までスタックします。$D1持続します。", nil, 0xf6dd7ebb, nil, "um" },
  [409947] = { "Earth Shieldのアビリティを得ます：\n\n$I1\n大地の盾で対象を守り、ダメージを受けたときに失う詠唱またはチャネリングの時間を$N1%減らし、攻撃を受けるとシールドを受けた対象の体力を$N2回復します。この効果は数秒に一度しか発生しません。チャージ$N3回。$D1持続します。Earth Shieldは一度に一つの対象にしかかけられません。", nil, 0x745da8e2, nil, "um" },
  [409951] = { "Spirit of the Alphaのアビリティを得ます：\n\n$I1\n対象にアルファウルフの魂を宿らせ、$D1の間、対象が発生させるすべての脅威を$N1%増加させます。対象は1体までです。自分以外の対象にかけた場合、シャーマンもLoyal Betaを得て、$D2の間、与えるPhysicalダメージが$N4%増加し、発生させるすべての脅威が$N5%減少します。一つの対象がSpirit of the AlphaとLoyal Betaを同時に持つことはできません。", nil, 0x95679687, nil, "um" },
  [409952] = { "Lava Burstのアビリティを得ます：\n\n$I1\n対象に溶岩を投げつけ、$N1のFireダメージを与えます。対象にFlame Shockがかかっている場合、Lava Burstのダメージが$N2%増加します。", nil, 0x93940084, nil, "um" },
  [409953] = { "Lava Lashのアビリティを得ます：\n\n$I1\nオフハンド武器に溶岩をまとわせ、即座にオフハンドのWeaponダメージの$N1%を与えます。オフハンド武器にFlametongueのエンチャントがかかっている場合、ダメージが$N2%増加します。", nil, 0xb4d0dacb, nil, "um" },
  [409954] = { "Riptideのアビリティを得ます：\n\n$I1\n味方の対象の体力を$N1回復し、さらに$D1かけて$N2回復し、その対象に直接詠唱するChain Healの効果を$N4%高めます。", nil, 0x16fbb037, nil, "um" },
  [409955] = { "Way of Earthのアビリティを得ます：\n\n$I1\nメインハンド武器にRockbiter Weaponが有効で盾を装備している間、発生する脅威が$N1%増加し、体力が$N2%増加し、受けるダメージが$N3%減少し、近接攻撃でクリティカルヒットを受ける確率が$N4%減少します。またEarth Shockが対象をTauntして自分を攻撃させるようになり、他のShock呪文とは別のクールダウンになりますが、射程は近接距離に短縮されます。ただし、Lightning Bolt、Chain Lightning、Chain Heal、Healing Wave、Lava Burstの呪文の射程が$N5ヤード短くなります。", nil, 0x4f96cd74, nil, "um" },
  [409957] = { "Steady Shotのアビリティを得ます：\n\n$I1\n狙いを定めた射撃で、遠隔武器ダメージの$N1%を与えます。", nil, 0x2697bd4f, nil, "um" },
  [409958] = { "Master Marksmanのアビリティを得ます：\n\n$I1\nクリティカル率が$N1%上昇し、すべてのShotのアビリティのマナコストが$N2%減少します。", nil, 0xdadd56b2, nil, "um" },
  [409959] = { "Expose Weaknessのアビリティを得ます：\n\n$I1\n近接攻撃と遠隔攻撃のクリティカルにより、$D1の間、現在の敏捷性の$N1%だけ攻撃力が上昇します。", nil, 0x3b41ea35, nil, "um" },
  [409960] = { "Cobra Slayerのアビリティを得ます：\n\n$I1\nMongoose Biteが近接攻撃のたびに$N1%の確率で使用可能になり、敵が回避したときは100%の確率で使用可能になります。この確率は蓄積し、リセットされなければ以後の攻撃ごとに$N3%ずつ上がります。Mongoose BiteはさらにAttack Powerの$N4%に等しい追加ダメージを与えます。", nil, 0x9c1a661a, nil, "um" },
  [409961] = { "Dual Wield Specialistのアビリティを得ます：\n\n$I1\nオフハンド武器の与えるダメージが$N1%増加し、二刀流の間はRaptor Strikeが両方の武器で攻撃するようになります。", nil, 0x7bbfdf06, nil, "um" },
  [409962] = { "Beast Masteryのアビリティを得ます：\n\n$I1\nペットの与えるダメージと体力が$N1%増加し、Focusの回復速度が$N2%上昇します。さらに、ペットのGrowlが$D1の間、対象をTauntしてペットを攻撃させるようにもなります。", nil, 0x9b4757cc, nil, "um" },
  [409974] = { "Kill Shotのアビリティを得ます：\n\n$I1\n手負いの対象にとどめを刺そうと遠隔攻撃を放ち、武器ダメージの$N1%に加えて$N2のダメージを与えます。Kill Shotには最小射程がありません。体力が20%以下の敵に使用すると、Kill Shotのクールダウンがリセットされます。", nil, 0xf8c116e8, nil, "um" },
  [409976] = { "Chimera Shotのアビリティを得ます：\n\n$I1\n武器ダメージの$N1%を与え、対象にかかっている現在のStingを更新し、効果を発動させます：\n\nSerpent Sting：Serpent Stingの与えるダメージの$N2%を即座に与えます。\n\nViper Sting：Viper Stingで吸い取った総量の$N3%に等しいマナを即座に回復します。\n\nScorpid Sting：$D1の間、対象のDisarmを試みます。この効果は1分に一度までしか発生しません。", nil, 0x5f9d939b, nil, "um" },
  [409979] = { "Lone Wolfのアビリティを得ます：\n\n$I1\n有効なペットがいない間、すべての攻撃で与えるダメージが$N1%増加します。", nil, 0x14ffc98e, nil, "um" },
})
